  function englishCount(value, one, many) {
    return value + " " + (Number(value) === 1 ? one : many);
  }

  function russianCount(value, one, few, many) {
    var number = Math.abs(Number(value));
    var mod100 = number % 100;
    var mod10 = number % 10;
    var form = mod10 === 1 && mod100 !== 11
      ? one
      : mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)
        ? few
        : many;
    return value + " " + form;
  }

